 function support(){return heading('Guia da plataforma','Ajuda e acesso','Como usar os fluxos do Torque Nutri.')+card('Nutricionista',`<ol><li>Cadastre ou importe os pacientes e confira e-mails e restrições.</li><li>Complete a anamnese, registre a consulta e envie os questionários.</li><li>Prepare o plano com biblioteca, metas e vigência. Salve o rascunho e publique quando revisar.</li><li>Convide o paciente pelo código vinculado ao e-mail confirmado.</li><li>Acompanhe diário, avaliações, pedidos de agenda e financeiro.</li></ol>`)+card('Paciente',`<ol><li>Entre com o e-mail cadastrado pelo consultório e resgate o convite.</li><li>Consulte o plano publicado, receitas e lista de compras.</li><li>Registre refeições consumidas, água e check-ins. Responda questionários e leia os documentos enviados.</li><li>Confira sua evolução, conquistas, consultas e pagamentos no Menu.</li></ol>`)+card('Confiabilidade',`<p class="sub">Rascunhos são isolados por conta e paciente. Edições concorrentes pedem atualização. Dados clínicos privados ficam com o profissional; a comunidade recebe apenas o que você publicar ali. Integrações externas mostram sua configuração real.</p>`);}
 function https(value){try{return new URL(value).protocol==='https:';}catch{return false;}}
 async function imageFile(file){if(!file||!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>10000000)throw Error('Escolha PNG, JPG ou WebP de até 10 MB.');const image=await createImageBitmap(file);const scale=Math.min(1,640/Math.max(image.width,image.height));const canvas=document.createElement('canvas');canvas.width=Math.round(image.width*scale);canvas.height=Math.round(image.height*scale);canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);image.close();const value=canvas.toDataURL('image/jpeg',.72);if(value.length>250000)throw Error('A foto ficou grande. Escolha uma imagem menor.');return value;}
 function download(name,data,type='application/json'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 function exportData(){download('torque-nutri-'+today()+'.json',{format:'torque-nutri',version:2,exportedAt:new Date().toISOString(),clinic:s().clinic,patients:s().patients,plans:s().plans,logs:s().logs,appointments:s().appointments,messages:s().messages,resources:s().resources,records:s().records,finances:s().finances});toast('Cópia exportada.');}
 function ics(x){const dt=z=>new Date(z).toISOString().replace(/[-:]/g,'').slice(0,15)+'Z';download('consulta.ics',`BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//Torque Nutri//Consulta//PT\r\nBEGIN:VEVENT\r\nUID:${x.id}@torque-nutri\r\nDTSTAMP:${dt(new Date())}\r\nDTSTART:${dt(x.start_at)}\r\nDTEND:${dt(new Date(new Date(x.start_at).getTime()+(x.duration_minutes||60)*60000))}\r\nSUMMARY:Consulta nutricional\r\nEND:VEVENT\r\nEND:VCALENDAR\r\n`,'text/calendar');}
 function printAssessment(x){return A.print(x);}

 function importPatients(){modal('Importar pacientes',`${area('Lista: nome; e-mail; objetivo','x-import','','required placeholder="Maria Souza; maria@exemplo.com; Organizar rotina"')}<p class="sub">Confira a prévia antes de importar. Pacientes já cadastrados com o mesmo e-mail são ignorados.</p><div id="x-import-preview"></div>`,async()=>{const rows=importRows();if(!rows.length)throw Error('Nenhuma linha válida para importar.');if(rows.length>500)throw Error('Importe até 500 pacientes por vez.');const fresh=rows.filter(x=>!s().patients.some(p=>p.email.toLowerCase()===x.email));if(s().demo)s().patients.push(...fresh.map(x=>({id:uid(),clinic_id:s().clinic.id,clinician_id:'demo',...x,restrictions:''})));else{H.errorCheck(await db().from('patients').insert(fresh.map(x=>({...x,clinic_id:s().clinic.id,clinician_id:s().user.id}))));await H.loadData();}render();toast(fresh.length+' pacientes importados.');});q('#x-import').oninput=()=>q('#x-import-preview').innerHTML=importRows().map(x=>row(x.name,x.email)).join('');}
 function importRows(){const rows=q('#x-import').value.split('\n').filter(x=>x.trim()).map(line=>{const [name,email,goal='']=line.split(/[;\t]/).map(x=>x.trim());return {name,email:(email||'').toLowerCase(),goal};}).filter(x=>x.name&&/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(x.email));return [...new Map(rows.map(x=>[x.email,x])).values()];}
